SELECT id, host, log_ts, level, latency_ms, status_code, payload_json, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region, CAST((status_code & 8) != 0 AS INT) AS flag_bit8 FROM app_logs
